// Shopping state stays in this browser; demo orders are separated by sign-in account.
function orderStorageKey(){return 'moodnote-demo-orders-v1-'+(window.moodnoteUser?.uid||'guest')}
function persistDemoOrder(orderNo){const summary=cartSummary();const orders=load(orderStorageKey(),[]);orders.unshift({id:orderNo,date:new Date().toISOString(),total:summary.total,items:summary.ids.map(id=>{const p=byId(id);return {id,name:p.name,image:p.image,price:p.price,quantity:cart[id],option:selections[id]||(p.options||['기본 옵션'])[0]}})});localStorage.setItem(orderStorageKey(),JSON.stringify(orders.slice(0,50)))}
function showMyPage(){setDrawer(false);['home-page','product-page','checkout-page'].forEach(id=>document.getElementById(id).hidden=true);document.getElementById('mypage-page').hidden=false;renderMyPage();window.scrollTo({top:0,behavior:'instant'})}
function renderMyPage(){
 const panel=document.getElementById('mypage-content');if(!panel)return;
 const user=window.moodnoteUser;const orders=load(orderStorageKey(),[]);const saved=favorites.map(byId).filter(Boolean);const count=Object.values(cart).reduce((a,b)=>a+b,0);
 panel.innerHTML=`<a href="#catalog" data-home class="back-link">← 문구 구경하기</a><div class="account-title"><span class="eyebrow">MY MOODNOTE</span><h1>나의 무드노트</h1><p>찜해둔 취향도, 골라둔 문구도 여기에서.</p></div><section class="account-profile"><img class="account-mark" src="assets/moodnote-mark-v2.svg" alt=""/><div><h2>${user?esc(user.displayName||'무드노트 회원')+'님, 반가워요.':'오늘의 취향을 모아볼까요?'}</h2><p>${user?esc(user.email||'Google 계정으로 로그인 중입니다.'):'Google 계정으로 로그인하고 나의 문구 목록을 확인하세요.'}</p></div><button class="outline-button" data-account-action="${user?'logout':'login'}">${user?'로그아웃':'Google 로그인'}</button></section><div class="account-stats"><a href="#my-orders" data-account-scroll="my-orders"><strong>${orders.length}</strong><span>데모 주문</span></a><a href="#my-favorites" data-account-scroll="my-favorites"><strong>${saved.length}</strong><span>찜한 상품</span></a><button data-action="cart"><strong>${count}</strong><span>장바구니</span></button></div><p class="account-note">찜과 장바구니는 현재 브라우저에 저장됩니다. 데모 주문 내역은 주문 당시의 로그인 계정별로 이 기기에 저장되며, 실제 결제·배송은 진행되지 않습니다.</p><section class="account-section" id="my-orders"><div class="account-section-head"><h2>주문 내역</h2><span>${orders.length}건</span></div>${orders.length?orders.map(order=>`<article class="account-order"><header><div><time>${esc(new Date(order.date).toLocaleDateString('ko-KR'))}</time><b>${esc(order.id)}</b></div><span class="account-demo">데모 주문 완료</span></header>${order.items.map(item=>`<div class="account-order-item"><button data-product="${esc(item.id)}" aria-label="${esc(item.name)} 상세 보기"><img src="${esc(item.image)}" alt="${esc(item.name)}"/></button><div><button class="account-product-name" data-product="${esc(item.id)}">${esc(item.name)}</button><p>${esc(item.option)} · ${item.quantity}개</p></div><strong>${won(item.price*item.quantity)}</strong></div>`).join('')}<footer><span>배송비·할인 포함 주문 합계</span><strong>${won(order.total)}</strong></footer></article>`).join(''):`<div class="account-empty"><span aria-hidden="true">▤</span><h3>아직 주문한 문구가 없어요</h3><p>주문서를 작성하면 데모 주문 내역이 여기에 모입니다.</p><a href="#catalog" data-home class="outline-button">상품 둘러보기</a></div>`}</section><section class="account-section" id="my-favorites"><div class="account-section-head"><h2>찜한 상품</h2><span>${saved.length}개</span></div>${saved.length?`<div class="account-favorites">${saved.map(p=>productCard(p)).join('')}</div>`:`<div class="account-empty"><span aria-hidden="true">♡</span><h3>마음에 드는 문구에 하트를 눌러보세요</h3><p>다음에 다시 보고 싶은 상품을 모아둘 수 있어요.</p><a href="#catalog" data-home class="outline-button">취향 찾으러 가기</a></div>`}</section><section class="account-help"><div><h2>도움이 필요하세요?</h2><p>배송·교환 안내와 고객센터 운영 시간을 확인하세요.</p></div><a href="#footer" data-home class="text-link">이용 안내 →</a></section>`;renderAddressBook();renderAccountExtras();
}
document.addEventListener('click',event=>{
 const link=event.target.closest('[data-mypage]');if(link){event.preventDefault();history.pushState({},'','#mypage');showMyPage();return}
 const scroll=event.target.closest('[data-account-scroll]');if(scroll){event.preventDefault();document.getElementById(scroll.dataset.accountScroll)?.scrollIntoView({behavior:'smooth'});return}
 const action=event.target.closest('[data-account-action]');if(action){if(action.dataset.accountAction==='login')document.getElementById('auth-button').click();else document.getElementById('auth-logout').click()}
});
window.addEventListener('moodnote-auth-change',()=>{if(!document.getElementById('mypage-page').hidden)renderMyPage()});
window.addEventListener('hashchange',()=>{if(location.hash==='#mypage')showMyPage()});
if(location.hash==='#mypage')showMyPage();

